'use strict';

var fs = require('fs');
var os = require('os');
var EOL = os.EOL;
var DELIM0 = String.fromCharCode(0);
var DELIM1 = String.fromCharCode(1);
var paths = require(__dirname + '/paths.js');
var exec = require('child_process').exec;

// read the contents of the package.json file
var packagePath = process.cwd() + '/package.json';
var packageInfo = fs.existsSync(packagePath) ? require(packagePath) : false;

var optionsParser = require(__dirname + '/options-parser.js');

var utilities = module.exports = {

  DELIM0: DELIM0,
  DELIM1: DELIM1,

  // pass options object to get the consolidated commandline argv
  // argv refers to process.argv by default
  // TODO: need a more elegant solution
  getAppmanArgv: function (options, argv) {

    var argvOptions = optionsParser(argv, null);

    // overwrite script options from commandline options
    if (argvOptions.daemon) options['daemon'] = true;
    if (argvOptions.revive) options['revive'] = true;
    if (argvOptions.enableApi) options['enable-api'] = true;
    if (argvOptions.watch) options['watch'] = true;
    if (argvOptions.audible) options['audible'] = true;

    if (argvOptions.file) options['file'] = argvOptions.file;
    if (argvOptions.watchFiles) options['watch-files'] = argvOptions.watchFiles;
    if (argvOptions.ignoreDirectories) options['ignore-directories'] = argvOptions.ignoreDirectories;
    if (argvOptions.crashCheckInterval) options['crash-check-interval'] = argvOptions.crashCheckInterval;
    if (argvOptions.revivalAttempts) options['revival-attempts'] = argvOptions.revivalAttempts;

    var booleans = ['watch', 'revive', 'daemon', 'enable-api'];
    var argv = process.argv.slice(0, 3);
    //console.log(options);
    //console.log(process.argv);

    Object.keys(options).forEach(function (key) {
      //console.log(options[key]);
      var val = options[key];
      if (booleans.indexOf(key) < 0) {
        argv.push('--' + key);
        argv.push(val);
      }
      else if (val) {
        argv.push('--' + key);
      }
    });

    return argv;

  },

  isNodeAppDirectory: function (path) {
    return fs.existsSync(path + '/package.json') ? true : false;
  },

  // create a file to flag app is being restarted
  setRestarting: function () {
    return fs.writeFileSync(paths.restartingFlag, '');
  },

  // remove the restart flag
  unsetRestarting: function () {
    return fs.unlinkSync(paths.restartingFlag);
  },

  appIsRestarting: function () {
    return (fs.existsSync(paths.restartingFlag)) ? true : false;
  },

  // convert seconds to human-friendly duration
  // TODO: make this more beautiful
  getDescriptiveDuration: function (seconds) {

    var secsInMinute = 60;
    var secsInHour = secsInMinute * 60;
    var secsInDay = secsInHour * 24;
    //var secsInMonth = secsInDay * 31;
    //var secsInYear = secsInMonth * 12;

    var duration = '';
    if (seconds >= secsInDay) {
      var days = Math.floor(seconds / secsInDay);
      duration += days + 'd';
      seconds = seconds % secsInDay;
    }

    if (seconds >= secsInHour) {
      if (duration.length) duration += ', ';
      var hours = Math.floor(seconds / secsInHour);
      duration += hours + 'h';
      seconds = seconds % secsInHour;
    }

    if (seconds >= secsInMinute) {
      if (duration.length) duration += ', ';
      var mins = Math.floor(seconds / secsInMinute);
      duration += mins + 'm';
      seconds = seconds % secsInMinute;
    }

    if (duration.length) duration += ', ';
    duration += Math.floor(seconds) + 's';

    return duration;
  },

  // log appman activities
  log: function (data) {
    var logData = Date() + ': ' + data + EOL;
    fs.appendFileSync(paths.appmanLog, logData);
  },

  // get the name and other details of the app
  info: function () {

    if (!packageInfo) return false;

    var name, version, mainFileName, mainFilePath;

    // the main file is specified in the package.json file
    if (packageInfo.main) mainFilePath = process.cwd() + '/' + packageInfo.main;
    // if not speficied look for index.js or main.js
    else {
      var fileNamedIndex = process.cwd() + '/index.js';
      var fileNamedMain = process.cwd() + '/main.js';
      if (fs.existsSync(fileNamedIndex)) mainFilePath = process.cwd() + '/' + fileNamedIndex;
      else if (fs.existsSync(fileNamedMain)) mainFilePath = process.cwd() + '/' + fileNamedMain;
    }

    mainFileName = mainFilePath.split('/').pop();

    if (packageInfo.name) name = packageInfo.name;
    else name = mainFileName;

    return {
      name: name,
      version: packageInfo.version,
      mainFileName: mainFileName,
      mainFilePath: mainFilePath
    }
  },

  // check if a process is alive
  alive: function (pid) {
    try {
      process.kill(pid, 0);
      return true;
    }
    catch (error) { return false; }
  },

  appIsAlive: function () {

    if (fs.existsSync(paths.appPid)) {
      var appPid = fs.readFileSync(paths.appPid);
      if (utilities.alive(appPid)) return true;
      else return false;
    }
    else { return false; }
  },

  getAppPid: function () {
    if (fs.existsSync(paths.appPid)) {
      var appPid = fs.readFileSync(paths.appPid);
      return appPid;
    }
    else { return false; }
  },

  monitorIsAlive: function () {
    if (fs.existsSync(paths.monitorPid)) {
      var monitorPid = fs.readFileSync(paths.monitorPid);
      if (utilities.alive(monitorPid)) return true;
      else return false;
    }
    else { return false; }
  },

  getMonitorPid: function () {
    if (fs.existsSync(paths.monitorPid)) {
      var monitorPid = fs.readFileSync(paths.monitorPid);
      return monitorPid;
    }
    else { return false; }
  },

  startScriptRunner: function () {

    var scriptRunnerLog = fs.openSync(paths.scriptRunnerLog, 'a');

    var scriptRunner = require('child_process').spawn('node', ['--harmony', paths.appmanScript, 'script'], {
      cwd: process.cwd(),
      env: process.env,
      stdio: ['ignore', scriptRunnerLog, scriptRunnerLog]
    });

    // record the scriptRunner's pid
    fs.writeFileSync(paths.scriptRunnerPid, scriptRunner.pid);

    scriptRunner.unref();

  },

  scriptRunnerIsAlive: function () {
    if (fs.existsSync(paths.scriptRunnerPid)) {
      var scriptRunnerPid = fs.readFileSync(paths.scriptRunnerPid);
      if (utilities.alive(scriptRunnerPid)) return true;
      else return false;
    }
    else { return false; }
  },

  getScriptRunnerPid: function () {
    if (fs.existsSync(paths.scriptRunnerPid)) {
      var scriptRunnerPid = fs.readFileSync(paths.scriptRunnerPid);
      return scriptRunnerPid;
    }
    else { return false; }
  },

  stopScriptRunner: function () {
    var scriptRunnerPid = fs.readFileSync(paths.scriptRunnerPid);
    return process.kill(scriptRunnerPid, 'SIGINT');
  },

  // appmanMasterRecordFile is the .appman file located in the user's home dir, where the running apps are registered
  appmanMasterRecordFileExists: function () {
    return fs.existsSync(paths.appmanMasterRecordFile) ? true : false;
  },

  // check appmanMasterRecordFileExists before calling this - everything will be overwritten
  createAppmanMasterRecordFile: function () {
    return fs.writeFileSync(paths.appmanMasterRecordFile, '');
  },

  deleteAppmanMasterRecordFile: function () {
    return fs.unlinkSync(paths.appmanMasterRecordFile);
  },

  readAppmanMasterRecordFile: function () {
    return (fs.existsSync(paths.appmanMasterRecordFile)) ? fs.readFileSync(paths.appmanMasterRecordFile).toString() : false;
  },

  listApps: function () {
    var apps = [];
    var fc = this.readAppmanMasterRecordFile();
    if (fc) {
      fc.split('\n').forEach(function (line) {
        if (line) {
          var segs = line.split(DELIM0, 5);
          var pid = +segs[0];
          var startedOn = +segs[3];
          // show only live apps
          if (utilities.alive(pid)) {
            var app = {
              name: segs[4],
              pid: pid,
              dirName: segs[1],
              fileName: segs[2],
              uptime: Math.floor((Date.now()/1000)) - startedOn,
              startedOn: startedOn
            };
            apps.push(app);
          }
          else { utilities.deregisterApp(pid); }
        }
      });
    }
    return apps;
  },

  registerApp: function (name, pid, dirName, fileName, startedOn, options) {
    // it is stored in this order to support space for app name
    var entry = pid + DELIM0 + dirName + DELIM0 + fileName + DELIM0 + startedOn + DELIM0 + name + DELIM0 + options + '\n';
    return fs.appendFileSync(paths.appmanMasterRecordFile, entry);
  },

  // this need not be called directly to update the appman file, because listApps syncs it during the query
  deregisterApp: function (pid) {

    var content = '';
    fs.readFileSync(paths.appmanMasterRecordFile).toString().split('\n').forEach(function (line) {
      if (line) {
        var segs = line.split(DELIM0, 5);
        if (pid != segs[0]) content += segs.join(DELIM0) + '\n';
      }
    });
    return fs.writeFileSync(paths.appmanMasterRecordFile, content);
  },

  getStartOptions: function (pid) {
    var options;
    var lines = fs.readFileSync(paths.appmanMasterRecordFile).toString().split('\n');
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i];
      var segs = line.split(DELIM0);
      if (pid == segs[0]) {
        options = segs[5];
        break
      }
    }
    return options;
  },

  say: function (text) {
    var sayCommand = 'say "'+ text +'"';
    if (os.platform() == 'darwin') exec(sayCommand);
  },

  terminateRunawayProcesses: function (cb) {

    var command = 'ps aux | grep node'; // Need a windows version
    exec(command, function (error, stdoutBuffer, stderrBuffer) {
      if (error) console.log(error);
      if (stderrBuffer) console.log(stderrBuffer);
      if (stdoutBuffer) {

        var runaways = false;
        var data = stdoutBuffer.toString();
        data.trim().split('\n').forEach(function (line) {

          var rprocess = line.split(/\s+/);

          if (rprocess.length > 11 && rprocess[rprocess.length-1] != 'script') {
            var pid = rprocess[1];
            var command = rprocess[10];
            var path;
            if (rprocess[11] == '--harmony') path = rprocess[12];
            else path = rprocess[11];
            // runaway process
            if (command == 'node' && path.indexOf(paths.appmanDir.replace('/.appman', '')) == 0) {
              runaways = true;
              process.kill(pid, 'SIGINT');
              console.log(' [1m[32m[22m[39m[0m Runaway process %s terminated', pid.toString().bold);
            }
          }

        });

        if (!runaways) console.log(' [1m[32m[22m[39m[0m No runaway processes');
        return cb && cb();

      }
    });
  }

};

