'use strict';

var fs = require('fs');
var net = require('net');
var paths = require(__dirname + '/paths.js');
var appmanUtils = require(__dirname + '/appmanutils.js');
var optionsParser = require(__dirname + '/options-parser.js');
var commandsFactory = require(__dirname + '/commands.js');

// get then app information object - if package.json file is not found, it will return false
var appInfo = appmanUtils.info();

if (appInfo) {
  // create the .appman dir, if not there already
  if (!fs.existsSync(paths.appmanDir)) fs.mkdirSync(paths.appmanDir);
  var appNameVersion = appInfo.name + (appInfo.version ? ' v' + appInfo.version : '');
}

// TODO: there might be a way to optimize this further
var command = process.argv[2];
var commands = commandsFactory(appNameVersion, appInfo);

// start the app - the responsibility of starting the app is actually handled by the monitor
if (command == 'start') {

  // there is a appman script
  if (process.argv.indexOf('--no-script') < 0 && fs.existsSync(paths.appmanScript)) {

    var scriptRunnerStarted = false;
    //appmanUtils.startScriptRunner();

    var scriptRunnerLog = fs.openSync(paths.scriptRunnerLog, 'a');

    var scriptRunner = require('child_process').spawn('node', ['--harmony', paths.appmanScript, 'script'], {
      cwd: process.cwd(),
      env: process.env,
      stdio: ['ignore', scriptRunnerLog, scriptRunnerLog, 'ipc']
    });

    scriptRunner.unref();

    // record the scriptRunner's pid
    fs.writeFileSync(paths.scriptRunnerPid, scriptRunner.pid);

    scriptRunner.on('message', function (msg) {

      if (msg == 'SERVICE_READY') {

        var srClient = net.connect({path: paths.scriptRunnerSock}, function (err) {
          if (err) throw err; // fail loudly
          srClient.write('options');
        });

        srClient.on('data', function (data) {

          srClient.end();

          var options = JSON.parse(data.toString());

          // create processArgv from options and process.argv
          var appmanArgv = appmanUtils.getAppmanArgv(options, process.argv);
          //console.log(appmanArgv);
          commands.startApp(appmanArgv);
        });

        srClient.on('error', function(err) {
          if (err.code == 'ENOENT' || err.code == 'ECONNREFUSED') { }
          else { console.log(err); }
        });

      }

    });

  }
  else { commands.startApp(process.argv); }

}

else {

  var program = optionsParser(process.argv, appInfo.version);

  // get status of the running app
  if (program.status) { commands.getAppStatus(program); }

  // get info about the app
  else if (program.info) { commands.getAppInfo(program); }

  // stop the app
  else if (program.stop) { commands.stopApp(program); }

  // restart the app - should specify the start params, else use the .appmanrc
  else if (program.restart) { commands.restartApp(program); }

  // clean up the dir, stop the monitor, kill any runaway processes
  else if (program.clean) { commands.cleanApp(program); }

  // stop the app, stop the monitor, delete the .appman dir, kill any runaway processes
  else if (program.reset) { commands.resetApp(program); }

  // list apps started by Appman
  else if (program.list) { commands.listApps(program); }

  else if (program.hack) {
    console.log(appmanUtils.getStartOptions(appmanUtils.getAppPid()));
  }

  else { program.help(); }

}

